logger = logging.getLogger(__name__)


def parse_timestamp_ms(value: str) -> int:
    """Parse epoch milliseconds or a timezone-aware ISO-8601 instant."""
    try:
        result = int(value)
    except ValueError:
        if re.match(r"^.*\+\d{2}:\d{2}Z$", value):
            raise argparse.ArgumentTypeError(
                "ISO-8601 timestamp must include a timezone offset like +02:00, or end with 'Z' for UTC, but not both.")
        try:
            parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError as exc:
            raise argparse.ArgumentTypeError(
                "Use Unix milliseconds (assumed UTC) or ISO-8601 with a timezone."
            ) from exc
        if parsed.tzinfo is None:
            raise argparse.ArgumentTypeError(
                "ISO-8601 timestamp must include a timezone."
            )
        result = int(parsed.timestamp() * 1000)

    if result < 0:
        raise argparse.ArgumentTypeError("Timestamp must not be negative.")
    return result


def nonnegative_int(value: str) -> int:
    """Parse an integer argument that must be zero or greater."""
    try:
        result = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("Expected an integer.") from exc
    if result < 0:
        raise argparse.ArgumentTypeError("Value must not be negative.")
    return result


def positive_int(value: str) -> int:
    """Parse an integer argument that must be greater than zero."""
    result = nonnegative_int(value)
    if result == 0:
        raise argparse.ArgumentTypeError("Value must be greater than zero.")
    return result


def print_as_json(value: dict) -> None:
    """Print one result as a JSON object on a single line."""
    print(json.dumps(value, ensure_ascii=False, default=str))


def configure_logging(level: str) -> None:
    """Configure diagnostics on stderr so stdout remains machine-readable."""
    logging.basicConfig(
        format="%(levelname)s: %(message)s",
        level=getattr(logging, level),
        stream=sys.stderr,
        force=True,
    )


def load_mapping(path: str) -> dict:
    """Load a JSON or YAML file and require its root value to be a mapping."""
    with Path(path).open(encoding="utf-8") as stream:
        try:
            result = yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            raise ValueError(f"Invalid JSON/YAML file: {path}") from exc

    if not isinstance(result, dict):
        raise ValueError(f"Expected a mapping in {path}.")
    return result


def load_source(project_secret_path: str, config_path: str) -> KafkaSource:
    """Load Kafka secrets from GSM and SourceConfig from JSON or YAML."""
    configuration = load_mapping(config_path)
    source_config = SourceConfig.model_validate(
        configuration.get("source", configuration)
    )

    # Reuse the project's Secret Manager loader, which places secret values in
    # the environment for KafkaSource's existing client configuration.
    os.environ["PROJECT_SECRET_PATH"] = project_secret_path
    set_secrets_as_envs()

    required = ["KAFKA_BROKERS", "KAFKA_CERTIFICATE", "KAFKA_PRIVATE_KEY", "KAFKA_CA"]

    kafka_secrets = {
        key: value
        for key, value in os.environ.items()
        if key.startswith("KAFKA_")
    }
    missing = [key for key in required if not kafka_secrets.get(key)]
    if missing:
        raise ValueError(
            f"Secret is missing required Kafka values: {', '.join(missing)}"
        )

    if source_config.schema_type == SchemaType.AVRO:
        missing = [
            key
            for key in (
                "KAFKA_SCHEMA_REGISTRY",
                "KAFKA_SCHEMA_REGISTRY_USER",
                "KAFKA_SCHEMA_REGISTRY_PASSWORD",
            )
            if not kafka_secrets.get(key)
        ]
        if missing:
            raise ValueError(
                f"Avro credentials are missing: {', '.join(missing)}"
            )

    return KafkaSource(source_config.model_dump(by_alias=True))


def check_partitions(partitions: list[TopicPartition]) -> None:
    """Raise Kafka's reported error if any returned partition has one."""
    for partition in partitions:
        if partition.error is not None:
            raise KafkaException(partition.error)


@dataclass(frozen=True)
class OffsetRange:
    start_offset: int
    end_offset: int
    limit: int


@dataclass(frozen=True)
class TimeRange:
    start_time_ms: int
    end_time_ms: int
    limit: int


class KafkaCLI:
    """Run development queries against one topic and consumer group.

    A Kafka topic is split into partitions. Each partition has its own ordered
    sequence of messages and its own offsets, so offset operations are always
    performed separately for each partition.
    """

    def __init__(self, source: KafkaSource, timeout: int):
        """Create a non-committing Kafka consumer from the source settings."""
        self.source = source
        self.timeout = timeout
        self.group_id = source.config.group_id
        self.topic = source.config.topic

        self.consumer_config = source._kafka_config()
        self.consumer_config.update(
            {
                # This CLI only inspects or explicitly edits stored group offsets.
                # Polling messages must never silently commit a new group position.
                "enable.auto.commit": False,
                "enable.auto.offset.store": False,
                # Emit an EOF event when an assigned partition reaches its end.
                "enable.partition.eof": True,
                # A typo in a topic should fail instead of creating a new topic.
                "allow.auto.create.topics": False,
            }
        )
        self.consumer = Consumer(self.consumer_config)

    def close(self) -> None:
        """Close the Kafka consumer and release its resources."""
        self.consumer.close()

    def partitions(self, selected: list[int] | None) -> list[TopicPartition]:
        """Return requested topic partitions, or all partitions by default."""
        # Fetch metadata first because partition numbers are specific to a topic
        # and may change when the topic is expanded.
        metadata = self.consumer.list_topics(timeout=self.timeout)
        topic = metadata.topics.get(self.topic)
        if topic is None:
            raise ValueError(f"Topic does not exist: {self.topic}")
        if topic.error is not None:
            raise KafkaException(topic.error)

        available = set(topic.partitions)
        requested = available if selected is None else set(selected)
        missing = requested - available
        if missing:
            raise ValueError(
                f"Unknown partitions for {self.topic}: {sorted(missing)}"
            )
        return [
            TopicPartition(self.topic, partition)
            for partition in sorted(requested)
        ]

    def watermarks(
            self, partitions: list[TopicPartition]
    ) -> dict[int, tuple[int, int]]:
        """Return earliest and end offsets indexed by partition ID.

        Kafka's low watermark is the oldest retained offset; its high watermark
        is the next offset that would be written. Therefore, valid message
        offsets are in [low, high), while high itself is a valid read position
        representing the end of the partition.
        """
        return {
            partition.partition: self.consumer.get_watermark_offsets(
                partition, timeout=self.timeout, cached=False
            )
            for partition in partitions
        }

    def offsets_at(
            self, partitions: list[TopicPartition], timestamp_utc_ms: int
    ) -> dict[int, int]:
        """Look up each partition's first offset at or after a timestamp.

        The returned offset is a candidate starting point, not a guarantee
        that all later records have increasing timestamps.
        """
        results = self.consumer.offsets_for_times(
            [
                TopicPartition(
                    partition.topic, partition.partition, timestamp_utc_ms
                )
                for partition in partitions
            ],
            timeout=self.timeout,
        )
        check_partitions(results)
        return {
            partition.partition: partition.offset
            for partition in results
        }

    def time_ranges(
            self,
            partitions: list[TopicPartition],
            start_timestamp_utc_ms: int,
            end_timestamp_utc_ms: int,
    ) -> dict[int, tuple[int, int]]:
        """Convert a timestamp interval into clamped, half-open offset ranges.

        The result is a pair of offsets [start, end) per partition. A Kafka
        timestamp lookup returns -1 when there is no matching record; in that
        case this function uses the partition's high watermark (its end).
        """
        watermarks = self.watermarks(partitions)
        starts = self.offsets_at(partitions, start_timestamp_utc_ms)
        ends = self.offsets_at(partitions, end_timestamp_utc_ms)

        result = {}
        for partition in partitions:
            partition_id = partition.partition
            low, high = watermarks[partition_id]
            # Kafka returns -1 when no message has a timestamp at or after the query.
            first = high if starts[partition_id] < 0 else starts[partition_id]
            last = high if ends[partition_id] < 0 else ends[partition_id]
            result[partition_id] = (
                max(low, min(first, high)),
                max(low, min(last, high)),
            )
        return result

    def timestamp_at_offset(self, partition: TopicPartition, offset: int) -> datetime|None:
        """Return the timestamp of a specific message offset in a partition."""
        try:
            messages = self._fetch([partition], OffsetRange(offset, offset + 1, 1))
        except TimeoutError:
            logger.warning("Timed out fetching timestamp of partition %d at offset %d, defaulting to None", partition.partition, offset)
            return None
        if len(messages) == 0:
            raise ValueError(f"No message found at offset {offset} in partition {partition.partition}.")
        return datetime.fromtimestamp(messages[0].timestamp()[1] / 1000, tz=UTC)

    def last_message_before_offset(self, partition: TopicPartition, offset: int, lookbehind=100) -> dict|None:
        """Return the last message in a partition, or None if the partition is empty.
        There may be a gap between the high watermark and the last message, so this function looks back a few messages.
        """
        low, high = self.watermarks([partition])[partition.partition]
        if high <= low:
            return None
        messages = self._fetch([partition], OffsetRange(max(low, offset - lookbehind), offset, lookbehind))
        if len(messages) == 0:
            logger.warning("No messages found in the last %d messages of partition %d before %d, defaulting to None", lookbehind, offset, partition.partition)
            return None
        return self.decode(messages[-1])

    def show_offsets(self, partitions: list[TopicPartition]) -> None:
        """Print committed group offsets, watermarks, and lag per partition.

        A committed group offset is the next message that group will read,
        rather than the last message it processed. Lag is estimated as the
        difference between that offset and the current high watermark.
        """
        committed = self.consumer.committed(
            partitions, timeout=self.timeout
        )
        check_partitions(committed)
        watermarks = self.watermarks(partitions)

        for partition in committed:
            low, high = watermarks[partition.partition]
            logger.debug("Watermarks for partition %d: low=%d, high=%d", partition.partition, low, high)
            logger.debug("Committed offset for partition %d: %d", partition.partition, partition.offset)
            committed_offset = partition.offset if partition.offset >= 0 else None
            ts_earliest_offset = self.timestamp_at_offset(partition, low) if high > low else None
            last_committed_message = self.last_message_before_offset(partition, committed_offset, lookbehind=20)
            last_message = self.last_message_before_offset(partition, high, lookbehind=20)
            print_as_json(
                {
                    "topic": partition.topic,
                    "partition": partition.partition,
                    "group_id": self.group_id,
                    "committed_offset": committed_offset,
                    "earliest_offset": low,
                    "end_offset": high,
                    "lag": None if committed_offset is None else max(0, high - committed_offset),
                    "timestamp_earliest_offset": ts_earliest_offset,
                    "last_committed_message": None if last_committed_message is None else {
                        "offset": last_committed_message["offset"],
                        "timestamp": last_committed_message["timestamp"],
                    },
                    "last_message": None if last_message is None else {
                        "offset": last_message["offset"],
                        "timestamp": last_message["timestamp"],
                    },
                }
            )

    def show_time_offsets(
            self,
            partitions: list[TopicPartition],
            start_timestamp_utc_ms: int,
            end_timestamp_utc_ms: int,
    ) -> None:
        """Print the candidate offset interval for each partition.

        Kafka stores timestamp indexes per partition, so a time query produces
        a separate start/end offset pair for every selected partition.
        """
        for partition_id, (first, last) in self.time_ranges(
                partitions, start_timestamp_utc_ms, end_timestamp_utc_ms
        ).items():
            print_as_json(
                {
                    "topic": self.topic,
                    "partition": partition_id,
                    "start_timestamp": datetime.fromtimestamp(start_timestamp_utc_ms / 1000, tz=UTC).isoformat(),
                    "end_timestamp": datetime.fromtimestamp(end_timestamp_utc_ms / 1000, tz=UTC).isoformat(),
                    "start_timestamp_utc_ms": start_timestamp_utc_ms,
                    "end_timestamp_utc_ms": end_timestamp_utc_ms,
                    "start_offset": first,
                    "end_offset": last,
                }
            )

    def decode(self, message) -> dict:
        """Decode a value using the configured schema and include Kafka metadata.

        Kafka stores keys and values as bytes. JSON and string values can be
        decoded directly; Avro values also require their schema from Schema
        Registry. Tombstone messages (null values) are represented as None.
        """
        raw = message.value()
        schema_id = None

        if raw is None:
            value = None
        elif self.source.config.schema_type == SchemaType.STRING:
            value = raw.decode("utf-8")
        elif self.source.config.schema_type == SchemaType.JSON:
            value = json.loads(raw)
        else:
            if len(raw) < 5 or raw[0] != 0:
                raise ValueError(
                    "Expected a Confluent Avro message with a schema ID."
                )
            schema_id = struct.unpack(">I", raw[1:5])[0]
            if schema_id not in self.source.schema_cache:
                schema_registry = os.environ["KAFKA_SCHEMA_REGISTRY"]
                logging.debug("Loading Avro schema %d from Schema Registry %s", schema_id, schema_registry)
                self.source.schema_cache[schema_id] = (
                    self.source._load_avro_schema(schema_id)
                )
            # Confluent's Avro wire format prefixes the payload with a magic byte and schema ID.
            decoder = avro.io.BinaryDecoder(io.BytesIO(raw[5:]))
            value = self.source.schema_cache[schema_id].read(decoder)

        result = {
            "topic": message.topic(),
            "partition": message.partition(),
            "offset": message.offset(),
            "timestamp_utc_ms": message.timestamp()[1],
            "timestamp": datetime.fromtimestamp(message.timestamp()[1] / 1000, tz=UTC).isoformat(),
            "key": self.source._key_deserializer(message.key()),
            "value": value,
        }
        if schema_id is not None:
            result["schema_id"] = schema_id
        return result

    def _get_ranges_for_fetch(
            self,
            partitions: list[TopicPartition],
            fetch_range: OffsetRange | TimeRange,
    ) -> dict[int, tuple[int, int]]:
        """Resolve a fetch request to an offset range per partition."""
        logger.debug(
            "Resolving fetch range %s for partitions %s",
            fetch_range,
            [partition.partition for partition in partitions],
        )
        if isinstance(fetch_range, OffsetRange):
            partition = partitions[0]
            low, high = self.watermarks(partitions)[partition.partition]
            if not low <= fetch_range.start_offset < high:
                raise ValueError(
                    f"Offset must be >= {low} and < {high} "
                    f"for partition {partition.partition}."
                )
            # End offsets are exclusive, so a single-message lookup reads [N, N+1).
            ranges = {
                partition.partition: (
                    fetch_range.start_offset,
                    min(fetch_range.end_offset, high),
                )
            }
        else:
            ranges = self.time_ranges(
                partitions,
                fetch_range.start_time_ms,
                fetch_range.end_time_ms,
            )
        logger.debug("Resolved fetch ranges: %s", ranges)
        return ranges

    def _assign_ranges(
            self, ranges: dict[int, tuple[int, int]]
    ) -> dict[int, int]:
        """Assign non-empty ranges and return their exclusive end offsets.

        Returns a dict of partition IDs to their exclusive end offsets.
        """
        pending = {}
        for partition_id, (start, end) in ranges.items():
            if start < end:
                pending[partition_id] = end
                logger.debug("Assigning to partition %s at offset: %s", partition_id, start)
            else:
                logger.debug(
                    "Skipping partition %s with empty range [%s, %s)",
                    partition_id,
                    start,
                    end,
                )

        # assign() reads only these partitions and positions; unlike subscribe(),
        # it does not join the group or use the group's committed offsets.
        if pending:
            assigned =  [
                TopicPartition(self.topic, partition_id, ranges[partition_id][0])
                for partition_id in pending
            ]
            self.consumer.assign(assigned)
            self.consumer.resume(assigned)
        return pending

    def _finish_partition(
            self, partition_end_offset_map: dict[int, int], partition: int
    ) -> None:
        """Pause a finished partition and remove it from the active fetch set."""
        if partition in partition_end_offset_map:
            logger.debug("Finished fetching partition %d", partition)
            self.consumer.pause([TopicPartition(self.topic, partition)])
            del partition_end_offset_map[partition]

    def _poll_messages(
            self,
            partition_end_offset_map: dict[int, int],
            fetch_range: OffsetRange | TimeRange,
    ) -> list:
        """Poll assigned partitions until their ranges or the message limit end."""
        messages = []
        count = 0
        deadline = monotonic() + self.timeout
        pending_partitions = partition_end_offset_map.copy()

        while pending_partitions and count < fetch_range.limit:
            remaining = deadline - monotonic()
            if remaining <= 0:
                raise TimeoutError(
                    f"Timed out fetching partitions {sorted(pending_partitions)}."
                )

            message = self.consumer.poll(min(1.0, remaining))
            if message is None:
                continue

            error = message.error()
            partition_id = message.partition()
            if error is not None:
                if error.code() != KafkaError._PARTITION_EOF:
                    raise KafkaException(error)
                if partition_id in pending_partitions:
                    logger.debug("Reached end of partition %d at offset %d", partition_id, message.offset())
                    self._finish_partition(pending_partitions, partition_id)
                deadline = monotonic() + self.timeout
                continue

            if partition_id not in pending_partitions:
                logger.debug("Ignoring message from inactive partition %d", partition_id)
                continue

            deadline = monotonic() + self.timeout
            end = pending_partitions[partition_id]
            if message.offset() >= end:
                logger.debug(
                    "Ignoring message at partition %d offset %d beyond exclusive end %d",
                    partition_id,
                    message.offset(),
                    end,
                )
                self._finish_partition(pending_partitions, partition_id)
                continue

            message_timestamp_utc_ms = message.timestamp()[1]
            if isinstance(fetch_range, OffsetRange) or (
                    fetch_range.start_time_ms
                    <= message_timestamp_utc_ms
                    < fetch_range.end_time_ms
            ):
                logger.debug(
                    "Added message from partition %d, offset %d",
                    partition_id,
                    message.offset(),
                )
                messages.append(message)
                count += 1
            else:
                logger.debug(
                    "Ignoring message from partition %d, offset %d outside timestamp range",
                    partition_id,
                    message.offset(),
                )

            if message.offset() + 1 >= end:
                self._finish_partition(pending_partitions, partition_id)

        logger.debug("Completed fetch with %d messages", len(messages))
        return messages

    def _fetch(self, partitions: list[TopicPartition], fetch_range: OffsetRange | TimeRange) -> list[Any]:
        ranges = self._get_ranges_for_fetch(partitions, fetch_range)
        partition_end_offset_map = self._assign_ranges(ranges)
        if partition_end_offset_map:
            messages = self._poll_messages(
                partition_end_offset_map,
                fetch_range,
            )
            return messages
        else:
            logger.debug("No non-empty fetch ranges to assign")
            return []

    def fetch(self, partitions: list[TopicPartition], args: argparse.Namespace) -> None:
        """Fetch messages from an offset or timestamp range without committing.

        A numeric offset can identify a message only within one partition.
        Timestamp queries instead find a candidate range in every selected
        partition and then check each message's actual timestamp.
        """
        if args.start_offset is not None:
            fetch_range = OffsetRange(
                args.start_offset,
                args.end_offset,
                args.limit,
            )
        else:
            fetch_range = TimeRange(
                args.start_time,
                args.end_time,
                args.limit,
            )

        messages = self._fetch(partitions, fetch_range)
        for message in messages:
            print_as_json(self.decode(message))
        if len(messages) >= args.limit:
            logging.warning(
                    "Fetch limit reached (%d messages); results may be incomplete.",
                    args.limit,
                )

    def set_offsets(self, partitions: list[TopicPartition], args: argparse.Namespace) -> None:
        """Preview or alter the group's committed position in each partition.

        Setting an offset changes where the group starts on its next read. It
        does not move a consumer that is already running, so execution is
        allowed only after Kafka reports the group has no active members.
        """
        watermarks = self.watermarks(partitions)
        timed = (
            self.offsets_at(partitions, args.timestamp)
            if args.timestamp is not None
            else None
        )

        changes = []
        for partition in partitions:
            low, high = watermarks[partition.partition]
            if args.earliest:
                offset = low
            elif args.latest:
                offset = high
            elif timed is not None:
                offset = timed[partition.partition]
                if offset < 0:
                    raise ValueError(f"No offset found for partition {partition.partition} at timestamp {args.timestamp}.")
            else:
                offset = args.offset

            if not low <= offset <= high:
                raise ValueError(
                    f"Offset {offset} is outside [{low}, {high}] "
                    f"for partition {partition.partition}."
                )
            changes.append(
                TopicPartition(self.topic, partition.partition, offset)
            )

        if args.execute:
            # AdminClient updates stored group offsets without consuming records.
            admin_config = {
                key: value
                for key, value in self.consumer_config.items()
                if key not in {
                    "group.id",
                    "auto.offset.reset",
                    "enable.auto.commit",
                    "enable.auto.offset.store",
                    "enable.partition.eof",
                    "allow.auto.create.topics",
                }
            }
            admin = AdminClient(admin_config)
            description = admin.describe_consumer_groups(
                [self.group_id], request_timeout=self.timeout
            )[self.group_id].result()

            # A live consumer can commit over this change immediately, so refuse
            # unless the group is stopped. Users should keep it stopped afterward.
            if description.state.name not in {"EMPTY", "DEAD"}:
                raise ValueError(
                    f"Group {self.group_id} is "
                    f"{description.state.name}; stop its consumers first."
                )

            result = admin.alter_consumer_group_offsets(
                [ConsumerGroupTopicPartitions(self.group_id, changes)],
                request_timeout=self.timeout,
            )[self.group_id].result()
            check_partitions(result.topic_partitions)

        for partition in changes:
            # Without --execute, output is a preview and Kafka is left unchanged.
            print_as_json(
                {
                    "topic": partition.topic,
                    "partition": partition.partition,
                    "group_id": self.group_id,
                    "offset": partition.offset,
                    "dry_run": not args.execute,
                }
            )


def _time_help_text(name: str) -> str:
    return f"{name}: Unix milliseconds (assumed UTC) or ISO-8601 with a timezone (e.g., 2023-01-01T00:00:00+02:00 or 2023-01-01T00:00:00Z for UTC)."

def build_parser() -> argparse.ArgumentParser:
    """Build the CLI parser, including global settings and operation commands."""
    parser = argparse.ArgumentParser(
        description="Development tools for Kafka messages and group offsets."
    )
    parser.add_argument(
        "--project-secret-path",
        default=os.environ.get("PROJECT_SECRET_PATH"),
        help=(
            "Google Secret Manager version resource name; defaults to "
            "PROJECT_SECRET_PATH."
        ),
    )
    parser.add_argument(
        "--config",
        default=os.environ.get("CONSUMER_CONFIG_PATH"),
        help="SourceConfig JSON/YAML file; defaults to CONSUMER_CONFIG_PATH.",
    )
    parser.add_argument(
        "--timeout",
        type=positive_int,
        default=10,
        help="Broker request and fetch idle timeout in seconds.",
    )
    parser.add_argument(
        "--log-level",
        type=str.upper,
        choices=("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"),
        default=os.getenv("LOG_LEVEL", "WARNING").upper(),
        help="Logging verbosity; defaults to LOG_LEVEL or WARNING.",
    )
    commands = parser.add_subparsers(dest="command", required=True)

    fetch = commands.add_parser(
        "fetch", help="Fetch messages without committing offsets. Use either offsets or timestamps"
    )
    selection = fetch.add_mutually_exclusive_group(required=True)
    selection.add_argument(
        "--offset",
        type=nonnegative_int,
        help="Fetch at this message offset; requires exactly one --partition.",
    )
    selection.add_argument(
        "--start-offset",
        type=nonnegative_int,
        help="Fetch from this message offset; requires exactly one --partition.",
    )
    selection.add_argument(
        "--start-time",
        type=parse_timestamp_ms,
        help=_time_help_text("Interval start"),
    )
    fetch.add_argument(
        "--end-offset",
        type=nonnegative_int,
        help="Exclusive ending offset; fetch stops before this offset.",
    )
    fetch.add_argument(
        "--end-time",
        type=parse_timestamp_ms,
        help=_time_help_text("Interval end"),
    )
    fetch.add_argument(
        "--limit",
        type=positive_int,
        default=100,
        help="Maximum number of messages to print (default: 100).",
    )

    offsets = commands.add_parser(
        "offsets", help="Show committed group offsets and watermarks."
    )

    times = commands.add_parser(
        "offsets-for-times", help="Query offsets for a timestamp range."
    )
    times.add_argument(
        "--start-time",
        type=parse_timestamp_ms,
        required=True,
        help=_time_help_text("Interval start"),
    )
    times.add_argument(
        "--end-time",
        type=parse_timestamp_ms,
        required=True,
        help=_time_help_text("Interval end"),
    )

    reset = commands.add_parser(
        "set-offset", help="Preview or change committed group offsets."
    )
    target = reset.add_mutually_exclusive_group(required=True)
    target.add_argument(
        "--offset",
        type=nonnegative_int,
        help="Set the group's next-read offset to this value.",
    )
    target.add_argument(
        "--timestamp",
        type=parse_timestamp_ms,
        help=_time_help_text("Timestamp"),
    )
    target.add_argument(
        "--earliest",
        action="store_true",
        help="Set the offset to the earliest retained message.",
    )
    target.add_argument(
        "--latest",
        action="store_true",
        help="Set the offset to the partition end (read new messages only).",
    )
    reset.add_argument(
        "--execute",
        action="store_true",
        help=(
            "Apply the changes; the group must be inactive and should remain "
            "stopped until the intended consumer resumes."
        ),
    )

    for command in (fetch, offsets, times, reset):
        command.add_argument(
            "--partition",
            type=nonnegative_int,
            action="append",
            help=(
                "Kafka partition ID to use; repeat to select multiple. "
                "Default: all partitions. Required with fetch --offset."
            ),
        )

    return parser

def _validate_time_args(parser: argparse.ArgumentParser, args: argparse.Namespace) -> None:
    if args.end_time is None:
        parser.error("--start-time requires --end-time.")
    elif args.start_time is None:
        parser.error("--end-time requires --start-time.")
    elif args.start_time >= args.end_time:
        parser.error(
            "--end-time must be greater than --start-time."
        )


def _validate_offset_args(parser: argparse.ArgumentParser, args: argparse.Namespace) -> None:
    if args.offset is not None:
        if args.start_offset is not None or args.end_offset is not None:
            parser.error(
                "--offset cannot be used with --start-offset or --end-offset."
            )
        if args.partition is None or len(set(args.partition)) != 1:
            parser.error("--offset requires exactly one --partition.")

        args.start_offset = args.offset
        args.end_offset = args.offset + 1
    if args.start_offset is not None:
        if args.end_offset is None:
            parser.error("--start-offset requires --end-offset.")

        # An offset has meaning only for one specific partition.
        if args.partition is None or len(set(args.partition)) != 1:
            parser.error("--start-offset requires exactly one --partition.")
        if args.end_offset <= args.start_offset:
            parser.error("--end-offset must be greater than --start-offset.")
    elif args.end_offset is not None:
        parser.error("--end-offset requires --start-offset.")


def validate_arguments(parser: argparse.ArgumentParser, args: argparse.Namespace) -> None:
    """Check required files, ranges, and incompatible options before connecting."""
    if not args.project_secret_path or not args.config:
        parser.error(
            "Provide --project-secret-path and --config, or set "
            "PROJECT_SECRET_PATH and CONSUMER_CONFIG_PATH."
        )

    if args.command == "fetch":
        offset_specified = args.offset is not None or args.start_offset is not None or args.end_offset is not None
        time_specified = args.start_time is not None or args.end_time is not None
        if offset_specified and time_specified:
            parser.error(
                "Use either --start-offset/--end-offset or "
                "--start-time/--end-time, not both."
            )
        elif offset_specified:
            _validate_offset_args(parser, args)
        elif time_specified:
            _validate_time_args(parser, args)
        else:
            parser.error(
                "Fetch requires either --start-offset/--end-offset or "
                "--start-time/--end-time."
            )

    if args.command == "offsets-for-times":
        _validate_time_args(parser, args)


def main() -> int:
    """Load configuration, run one command, and return its process exit code."""
    parser = build_parser()
    args = parser.parse_args()
    validate_arguments(parser, args)
    configure_logging(args.log_level)

    try:
        source = load_source(args.project_secret_path, args.config)
        logger.info("Loaded source configuration for topic %s and group %s",
                    source.config.topic, source.config.group_id)
        brokers = os.environ["KAFKA_BROKERS"]
        logger.info("Using Kafka brokers: %s", brokers)

        cli = KafkaCLI(source, args.timeout)
        try:
            partitions = cli.partitions(args.partition)
            if args.command == "fetch":
                cli.fetch(partitions, args)
            elif args.command == "offsets":
                cli.show_offsets(partitions)
            elif args.command == "offsets-for-times":
                cli.show_time_offsets(
                    partitions,
                    args.start_time,
                    args.end_time,
                )
            else:
                cli.set_offsets(partitions, args)
        finally:
            # Always close the Kafka connection, including after a command error.
            cli.close()
    except (
            OSError,
            ValueError,
            KeyError,
            KafkaException,
            requests.RequestException,
    ) as exc:
        if args.log_level == "DEBUG":
            logging.exception("Exception during command execution")
        else:
            print(f"Error: {exc}\n\nAdd --log-level DEBUG to see the exception", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        return 130

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
